class Program {
    static class Base {
        Base() { System.out.println("base"); }
        int value() { return 2; }
    }
    static class Child extends Base {
        Child() { super(); System.out.println("child"); }
        @Override int value() { return 7; }
    }
    public static void main(String[] args) {
        Base item = new Child();
        System.out.println(item.value());
    }
}
